def transform(grid):
    # Extract the rectangular canvas of the main design.
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 1]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    out = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]

    # The isolated colored marks outside the canvas indicate the positions
    # for the corresponding colors along its border.
    marks = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v not in (0, 1) and not (r0 <= r <= r1 and c0 <= c <= c1):
                marks.setdefault(v, []).append((r, c))
    h, w = len(out), len(out[0])
    for color, pts in marks.items():
        if color not in (2, 3, 4, 5, 8):
            continue
        r, c = pts[0]
        # Use the side of the canvas nearest the isolated mark.
        if r < r0:
            rr, cc = 0, max(0, min(w - 1, c - c0))
        elif r > r1:
            rr, cc = h - 1, max(0, min(w - 1, c - c0))
        elif c < c0:
            rr, cc = max(0, min(h - 1, r - r0)), 0
        else:
            rr, cc = max(0, min(h - 1, r - r0)), w - 1
        out[rr][cc] = color
    return out
